mapper.select:
SELECT 

  AND c.id > #{afterChunkId}
ORDER BY c.id ASC LIMIT #{limit}

SELECT 

  AND d.id = #{documentId}
ORDER BY c.chunk_index ASC

SELECT 

  AND c.document_id = #{documentId}
  AND MATCH(c.content) AGAINST(#{keyword} IN BOOLEAN MODE)
ORDER BY MATCH(c.content) AGAINST(#{keyword} IN BOOLEAN MODE) DESC, c.id ASC
LIMIT #{limit}

SELECT


  AND c.document_id = #{documentId}
  AND c.chunk_index >= #{startIndex}
ORDER BY c.chunk_index ASC
LIMIT #{limit}

SELECT


  AND c.id = #{chunkId}
  AND c.document_id = #{documentId}
  AND d.parse_version = #{parseVersion}
